.research-focus,.loop-panel,.validation-map,.ablation-panel,.timeline,.governance-chart,.twin-pipeline,.research-finding,.boundary-panel{border:1px solid #2a2428;border-radius:8px;background:#151113;box-shadow:none;color:#f1ece7}.research-focus{grid-template-columns:10rem minmax(0,1fr);padding:var(--cp-space-4)}.focus-marker{color:#51464c;font-size:1.4rem}.focus-grid article,.innovation-card,.loop-diagram>div,.metric-grid article,.validation-map li,.case-grid article,.chart-cases article,.trajectory-card,.trajectory-plot,.timeline em{border:1px solid #2a2428;border-radius:6px;background:#1c1719;box-shadow:none;color:#f1ece7}.focus-grid article{padding:var(--cp-space-3)}.focus-grid article>span,.focus-grid article>small,.focus-grid p,.innovation-card header,.innovation-card .card-kicker,.case-grid article>span,.case-link,.trajectory-card header span,.trajectory-card dt{color:#9e958f}.focus-grid article>span{font-size:2rem}.focus-grid article:hover,.innovation-card:hover,.trajectory-card:hover{border-color:#51464c;box-shadow:none;transform:none}.chapter-heading{padding-left:0;border-bottom-color:#2a2428}.chapter-heading:before{display:none}.chapter-number{background:none;color:#9e958f;text-shadow:none}.innovation-grid{gap:var(--cp-space-2)}.innovation-card{min-height:0;padding:var(--cp-space-4);transition:border-color var(--cp-motion-standard) ease}.innovation-card header i{width:2.5rem;height:2.5rem;border:1px solid #2a2428;border-radius:6px;background:#151113;box-shadow:none}.innovation-card p,.case-grid p,.loop-copy p,.twin-pipeline header p,.trajectory-card p{color:#b9b0aa;line-height:1.6}.innovation-card li{padding:.35rem .55rem;border:1px solid #2a2428;border-radius:4px;background:#151113;color:#9e958f}
